import numpy as np
from scipy.optimize import least_squares
forms={
 'hill': lambda p,a: p[0]+p[1]*a**p[3]/(p[2]**p[3]+a**p[3]),
 'weib': lambda p,a: p[0]+p[1]*(1-np.exp(-p[2]*a**p[3])),
 'expo_lin': lambda p,a: p[0]+p[1]*a*np.exp(-p[2]*a)+p[3]*a,
 'poly3': lambda p,a: p[0]+p[1]*a+p[2]*a**2+p[3]*a**3,
}
def fit(f,lo,hi):
    m=(t>=lo)&(t<hi); a=A[m]; y=dA_dt[m]
    best=None
    rng=np.random.default_rng(1)
    for i in range(40):
        p0=rng.uniform(0.3,3,size=4); p0[0]=-9
        try: s=least_squares(lambda p: f(p,a)-y,p0,max_nfev=3000)
        except Exception: continue
        if best is None or s.cost<best.cost: best=s
    return np.sqrt(np.mean(best.fun**2)).round(3), np.round(best.x,3)
for lo,hi in [(4.5,5.5),(9,10),(2,3),(7,8)]:
    print("slice",lo,hi)
    for k,f in forms.items():
        print("  ",k,fit(f,lo,hi))
